DROP TABLE IF EXISTS nbfc_001.account_details;
CREATE TABLE nbfc_001.account_details (
	loan_id VARCHAR(20) NOT NULL, 
	customer_id VARCHAR(20) NOT NULL, 
	party_role VARCHAR(10), 
	loan_number VARCHAR(30), 
	branch_code VARCHAR(10), 
	product_code VARCHAR(20), 
	member_code VARCHAR(10), 
	member_short_name VARCHAR(16), 
	sanction_amount NUMERIC(20, 2), 
	disbursement_date DATE, 
	last_payment_date DATE, 
	closed_date DATE, 
	reported_date DATE, 
	outstanding_amount NUMERIC(20, 2), 
	overdue_amount NUMERIC(20, 2), 
	days_past_due INTEGER, 
	asset_classification VARCHAR(10), 
	suit_status VARCHAR(20), 
	facility_status VARCHAR(30), 
	collateral_type VARCHAR(20), 
	collateral_value NUMERIC(20, 2), 
	credit_limit NUMERIC(20, 2), 
	cash_limit NUMERIC(20, 2), 
	interest_rate_percent NUMERIC(8, 3), 
	tenure_months INTEGER, 
	emi_amount NUMERIC(20, 2), 
	writeoff_total_amount NUMERIC(20, 2), 
	writeoff_principal_amount NUMERIC(20, 2), 
	settlement_amount NUMERIC(20, 2), 
	pay_frequency VARCHAR(20), 
	last_payment_amount NUMERIC(20, 2), 
	previous_member_code VARCHAR(10), 
	previous_member_short_name VARCHAR(16), 
	previous_loan_number VARCHAR(30), 
	previous_product_code VARCHAR(20), 
	previous_party_role VARCHAR(10), 
	test_scenario_number INTEGER, 
	test_expected VARCHAR(30), 
	test_rule_reference VARCHAR(30), 
	test_description VARCHAR(255), 
	PRIMARY KEY (loan_id, customer_id)
);
