DROP TABLE IF EXISTS nbfc_002.business_borrower;
CREATE TABLE nbfc_002.business_borrower (
	customer_id VARCHAR(20) NOT NULL, 
	business_name VARCHAR(150), 
	short_name VARCHAR(20), 
	constitution VARCHAR(10), 
	msme_category VARCHAR(10), 
	industry VARCHAR(10), 
	bsr_activity_1 VARCHAR(5), 
	bsr_activity_2 VARCHAR(5), 
	bsr_activity_3 VARCHAR(5), 
	hsn_code VARCHAR(20), 
	incorporation_date DATE, 
	turnover NUMERIC(20, 2), 
	turnover_fy DATE, 
	employees INTEGER, 
	rating VARCHAR(10), 
	rating_agency VARCHAR(20), 
	rating_date DATE, 
	rating_valid_till DATE, 
	pan VARCHAR(20), 
	cin VARCHAR(30), 
	tin VARCHAR(30), 
	service_tax VARCHAR(30), 
	udyam VARCHAR(30), 
	company_reg_no VARCHAR(30), 
	ckyc VARCHAR(30), 
