DROP TABLE IF EXISTS nbfc_002.business_facility;
CREATE TABLE nbfc_002.business_facility (
	facility_id VARCHAR(20) NOT NULL, 
	customer_id VARCHAR(20), 
	facility_number VARCHAR(30), 
	branch_code VARCHAR(10), 
	product VARCHAR(20), 
	sanction_date DATE, 
	sanction_amount NUMERIC(20, 2), 
	currency VARCHAR(3), 
	tenure_months INTEGER, 
	frequency VARCHAR(20), 
	drawing_power NUMERIC(20, 2), 
	outstanding NUMERIC(20, 2), 
	maturity_date DATE, 
	renewal_date DATE, 
	dpd INTEGER, 
	asset_class VARCHAR(10), 
	asset_class_date DATE, 
	overdue NUMERIC(20, 2), 
	bucket_1 NUMERIC(20, 2), 
	bucket_2 NUMERIC(20, 2), 
	bucket_3 NUMERIC(20, 2), 
	bucket_4 NUMERIC(20, 2), 
	bucket_5 NUMERIC(20, 2), 
	high_credit NUMERIC(20, 2), 
	instalment NUMERIC(20, 2), 
	last_paid NUMERIC(20, 2), 
	last_paid_date DATE, 
	status VARCHAR(20), 
	status_date DATE, 
	closed_date DATE, 
	written_off NUMERIC(20, 2), 
	settled NUMERIC(20, 2), 
	restructure_reason VARCHAR(20), 
	security_cover VARCHAR(10), 
	guarantee_cover VARCHAR(10), 
	remark VARCHAR(100), 
	wilful_date DATE, 
	suit_status VARCHAR(20), 
	suit_ref VARCHAR(25), 
	suit_amount NUMERIC(20, 2), 
	suit_date DATE, 
	test_scenario_number INTEGER, 
	test_expected VARCHAR(30), 
	test_rule_reference VARCHAR(40), 
	test_description VARCHAR(255), 
	PRIMARY KEY (facility_id)
);
