DROP TABLE IF EXISTS nbfc_002.facility_guarantor;
CREATE TABLE nbfc_002.facility_guarantor (
	facility_id VARCHAR(20) NOT NULL, 
	guarantor_id VARCHAR(20) NOT NULL, 
	invocation_date DATE, 
	kind VARCHAR(15), 
	name VARCHAR(150), 
	prefix VARCHAR(15), 
	gender VARCHAR(2), 
	dob DATE, 
	incorporation_date DATE, 
	pan VARCHAR(20), 
	voter_id VARCHAR(30), 
	passport VARCHAR(30), 
	dl VARCHAR(30), 
	aadhaar VARCHAR(30), 
	ration_card VARCHAR(30), 
	cin VARCHAR(30), 
	din VARCHAR(12), 
	tin VARCHAR(30), 
	service_tax VARCHAR(30), 
	ckyc VARCHAR(30), 
	udyam VARCHAR(30), 
	company_reg_no VARCHAR(30), 
	category VARCHAR(10), 
	industry VARCHAR(10), 
	line1 VARCHAR(150), 
	line2 VARCHAR(150), 
	line3 VARCHAR(150), 
	city VARCHAR(40), 
	district VARCHAR(40), 
	state VARCHAR(40), 
	pin VARCHAR(10), 
	country VARCHAR(2), 
	mobile VARCHAR(60), 
	phone VARCHAR(60), 
	phone_area VARCHAR(6), 
	PRIMARY KEY (facility_id, guarantor_id)
);
