DROP TABLE IF EXISTS nbfc_002.facility_security;
CREATE TABLE nbfc_002.facility_security (
	facility_id VARCHAR(20) NOT NULL, 
	seq INTEGER NOT NULL, 
	value NUMERIC(20, 2), 
	currency VARCHAR(3), 
	sec_type VARCHAR(20), 
	charge VARCHAR(20), 
	valuation_date DATE, 
	PRIMARY KEY (facility_id, seq)
);
