DROP TABLE IF EXISTS nbfc_002.facility_cheque_bounce;
CREATE TABLE nbfc_002.facility_cheque_bounce (
	facility_id VARCHAR(20) NOT NULL, 
	seq INTEGER NOT NULL, 
	bounce_date DATE, 
	amount NUMERIC(20, 2), 
	cheque_no VARCHAR(30), 
	times INTEGER, 
	cheque_date DATE, 
	reason VARCHAR(10), 
	PRIMARY KEY (facility_id, seq)
);
